import java.io.*;
import java.util.*;

public class Main {
    static boolean isLucky(long x) {
        if (x <= 0) return false;
        while (x > 0) {
            long d = x % 10;
            if (d != 4 && d != 7) return false;
            x /= 10;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        long k = Long.parseLong(st.nextToken());

        // Precompute factorials up to 20 (since 20! fits in long, 21! doesn't)
        int MAXF = 20;
        long[] fact = new long[MAXF + 1];
        fact[0] = 1;
        for (int i = 1; i <= MAXF; i++) {
            fact[i] = fact[i - 1] * i;
            if (fact[i] < 0) fact[i] = Long.MAX_VALUE; // safety
        }

        if (n <= MAXF) {
            if (k > fact[(int) n]) {
                System.out.println(-1);
                return;
            }
            // Build k-th permutation of 1..n
            List<Integer> nums = new ArrayList<>();
            for (int i = 1; i <= n; i++) nums.add(i);
            int[] perm = new int[(int) n + 1]; // 1-based

            long kk = k - 1; // 0-based index
            for (int pos = 1; pos <= n; pos++) {
                int remaining = (int) (n - pos);
                long block = remaining >= 0 ? fact[remaining] : 1;
                int idx = (int) (kk / block);
                kk %= block;
                perm[pos] = nums.get(idx);
                nums.remove(idx);
            }

            int ans = 0;
            for (int i = 1; i <= n; i++) {
                if (isLucky(i) && isLucky(perm[i])) ans++;
            }
            System.out.println(ans);
        } else {
            // n > 20: only last 20 positions can vary
            int tail = MAXF;
            long fixed = n - tail; // positions 1..fixed are fixed as i
            if (k > fact[tail]) {
                System.out.println(-1);
                return;
            }

            // Build k-th permutation of the tail values: fixed+1 .. n
            List<Integer> nums = new ArrayList<>();
            for (int i = (int) (fixed + 1); i <= n; i++) nums.add(i);
            int[] tailPerm = new int[tail + 1]; // 1-based within tail

            long kk = k - 1;
            for (int pos = 1; pos <= tail; pos++) {
                int remaining = tail - pos;
                long block = fact[remaining];
                int idx = (int) (kk / block);
                kk %= block;
                tailPerm[pos] = nums.get(idx);
                nums.remove(idx);
            }

            int ans = 0;
            // Count in fixed part: a[i] = i
            for (long i = 1; i <= fixed; i++) {
                if (isLucky(i)) ans++;
            }
            // Count in tail part
            for (int offset = 1; offset <= tail; offset++) {
                long pos = fixed + offset;
                if (isLucky(pos) && isLucky(tailPerm[offset])) ans++;
            }
            System.out.println(ans);
        }
    }
}

